import unittest


class Test_slicing_and_find(unittest.TestCase):
    def test_slice_start_and_end(self) -> None:
        self.assertEqual(
            'bc',
            'abcde'[1:3]
        )

    def test_slice_no_start(self) -> None:
        self.assertEqual(
            'ab',
            'abcde'[:2]
        )

    def test_slice_no_end(self) -> None:
        self.assertEqual(
            'de',
            'abcde'[3:]
        )

    def test_slice_neither_start_nor_end(self) -> None:
        self.assertEqual(
            'abcde',
            'abcde'[:]
        )

    def test_slice_negative_start_counts_from_the_end(self) -> None:
        self.assertEqual(
            'de',
            'abcde'[-2:]
        )

    def test_slice_negative_end_counts_from_the_end(self) -> None:
        self.assertEqual(
            'abc',
            'abcde'[:-2]
        )

    def test_slice_negative_start_and_end(self) -> None:
        self.assertEqual(
            'bcd',
            'abcde'[-4:-1]
        )

    def test_slice_negative_start_before_the_beginning_is_clamped(self) -> None:
        self.assertEqual(
            'ab',
            'abcde'[-10:2]
        )

    def test_slice_end_beyond_the_end_is_clamped(self) -> None:
        self.assertEqual(
            'cde',
            'abcde'[2:10]
        )

    def test_slice_start_beyond_the_end_gives_empty(self) -> None:
        self.assertEqual(
            '',
            'abcde'[10:]
        )

    def test_slice_start_after_end_gives_empty(self) -> None:
        self.assertEqual(
            '',
            'abcde'[3:1]
        )

    def test_slice_negative_start_after_negative_end_gives_empty(self) -> None:
        self.assertEqual(
            '',
            'abcde'[-1:-3]
        )

    def test_slice_start_equal_to_end_gives_empty(self) -> None:
        self.assertEqual(
            '',
            'abcde'[5:5]
        )

    def test_slice_empty_text(self) -> None:
        self.assertEqual(
            '',
            ''[0:0]
        )

    def test_slice_negative_start_on_empty_text(self) -> None:
        self.assertEqual(
            '',
            ''[-1:]
        )

    def test_slice_end_beyond_the_end_of_empty_text(self) -> None:
        self.assertEqual(
            '',
            ''[:5]
        )

    def test_find_found(self) -> None:
        self.assertEqual(
            1,
            'abcabc'.find('b')
        )

    def test_find_not_found(self) -> None:
        self.assertEqual(
            -1,
            'abcabc'.find('x')
        )

    def test_find_empty_sub(self) -> None:
        self.assertEqual(
            0,
            'abcabc'.find('')
        )

    def test_find_sub_longer_than_text(self) -> None:
        self.assertEqual(
            -1,
            'ab'.find('abc')
        )

    def test_find_found_after_start(self) -> None:
        self.assertEqual(
            4,
            'abcabc'.find('b', 2)
        )

    def test_find_found_only_before_start(self) -> None:
        self.assertEqual(
            -1,
            'abcabc'.find('b', 5)
        )

    def test_find_negative_start_counts_from_the_end(self) -> None:
        self.assertEqual(
            5,
            'abcabc'.find('c', -1)
        )

    def test_find_negative_start_finds_the_later_occurrence(self) -> None:
        self.assertEqual(
            3,
            'abcabc'.find('a', -3)
        )

    def test_find_negative_start_before_the_beginning_is_clamped(self) -> None:
        self.assertEqual(
            0,
            'abcabc'.find('a', -10)
        )

    def test_find_empty_sub_at_the_end(self) -> None:
        self.assertEqual(
            6,
            'abcabc'.find('', 6)
        )

    def test_find_empty_sub_beyond_the_end_gives_1(self) -> None:
        self.assertEqual(
            -1,
            'abcabc'.find('', 7)
        )

    def test_find_start_beyond_the_end_gives_1(self) -> None:
        self.assertEqual(
            -1,
            'abcabc'.find('c', 10)
        )

    def test_find_empty_sub_in_empty_text(self) -> None:
        self.assertEqual(
            0,
            ''.find('')
        )

    def test_find_empty_sub_beyond_the_end_of_empty_text_gives_1(self) -> None:
        self.assertEqual(
            -1,
            ''.find('', 1)
        )

    def test_find_not_found_in_empty_text(self) -> None:
        self.assertEqual(
            -1,
            ''.find('x')
        )


